/* Original French introductory lessons. External videos are optional complements. */
function buildCurriculum(L){
const make=(id,title,category,domain,desc,glyph,color,rows)=>({id,title,en:title,category,domain,desc,enDesc:desc,glyph,color,type:'subject',level:'Débutant',duration:rows.length*10,lessons:rows.map(r=>L(...r))});
return [
make('algorithms','La logique avant le code','LOGIQUE & ALGORITHMES','tech','Décompose un problème, trouve une méthode et apprends à penser comme un programmeur.','↳','#dcead8',[
['Une recette pour résoudre un problème','Un algorithme est une suite d’étapes précises pour obtenir un résultat. Avant de coder, on peut écrire ces étapes en français. Pour préparer un trajet, on choisit une destination, on compare les possibilités, puis on vérifie le coût. L’ordre et les informations de départ comptent.','1. Lire le prix du trajet\n2. Lire le nombre de trajets\n3. Multiplier\n4. Afficher le budget','Un budget obtenu étape par étape.','Quelle description est un algorithme ?',['Sois intelligent','Lis deux nombres, additionne-les, affiche le résultat','Un ordinateur'],1,'Les instructions sont ordonnées, précises et réalisables.'],
['Repérer les informations utiles','Résoudre un problème commence par distinguer les entrées, le traitement et la sortie. Si tu calcules un budget, les entrées sont le prix et la quantité. Le traitement est la multiplication. La sortie est le montant total.','Entrées : 200 FCFA, 4 trajets\nTraitement : 200 × 4\nSortie : 800 FCFA','800 FCFA','Dans cet exemple, quelle est la sortie ?',['Le nombre de trajets','Le montant total','Le nom du chauffeur'],1,'La sortie est le résultat produit par le traitement.'],
['Choisir et répéter','Certaines étapes dépendent d’une condition. D’autres se répètent. Pour vérifier une liste d’achats, on peut répéter un contrôle pour chaque produit et décider si le budget suffit. Une condition a une réponse vraie ou fausse.','Pour chaque article :\n  Si prix ≤ budget restant :\n    Ajouter au panier\n  Sinon :\n    Passer au suivant','Une décision répétée pour chaque article.','Quel mot indique une répétition ?',['Pour chaque','Sinon','Prix'],0,'« Pour chaque » applique les mêmes étapes à plusieurs éléments.'],
['Trouver une erreur de logique','Un programme peut suivre des instructions correctes dans un mauvais ordre. Tester avec un petit exemple aide à détecter l’erreur. Explique ton raisonnement sur papier, vérifie une étape à la fois, puis compare le résultat attendu et le résultat obtenu.','But : calculer la moyenne de 10 et 14\nIncorrect : 10 + 14 / 2 = 17\nCorrect : (10 + 14) / 2 = 12','Les parenthèses changent l’ordre du calcul.','Quelle moyenne obtient-on pour 8 et 16 ?',['12','16','24'],0,'On additionne 8 et 16, puis on divise le total 24 par 2 : 12.']
]),
make('javascript','JavaScript, de l’idée à l’action','PROGRAMMATION','tech','Variables, conditions, fonctions : fais réagir tes premières interfaces.','JS','#f5edbb',[
['Garder une valeur','En JavaScript, const sert à déclarer une variable dont on ne réaffectera pas la valeur. let convient à une variable que l’on veut modifier. Un texte s’écrit entre guillemets ; un nombre peut être utilisé dans un calcul.','const ville = "Lomé";\nlet points = 2;\npoints = points + 3;\nconsole.log(points);','5','Quelle déclaration permet de réaffecter une valeur ?',['let','const','console'],0,'let autorise une réaffectation. const l’empêche.'],
['Choisir avec une condition','if exécute un bloc si une condition est vraie. else exécute une autre action. Le symbole === compare des valeurs sans conversion automatique de type. Il ne faut pas le confondre avec =, qui affecte une valeur.','const disponible = true;\nif (disponible === true) {\n  console.log("Bienvenue !");\n} else {\n  console.log("À bientôt !");\n}','Bienvenue !','Quel signe sert ici à comparer ?',['=','===','+'],1,'=== compare ; = affecte une valeur.'],
['Réutiliser une fonction','Une fonction réalise une tâche. Les paramètres sont les informations reçues. return produit un résultat que l’on peut utiliser ailleurs. Donne à la fonction un nom qui décrit clairement son rôle.','function total(prix, nombre) {\n  return prix * nombre;\n}\nconsole.log(total(200, 3));','600','Que renvoie total(100, 4) ?',['104','400','1004'],1,'La fonction multiplie les deux paramètres : 100 × 4 = 400.'],
['Parcourir une liste','Un tableau contient plusieurs valeurs. La boucle for...of parcourt les valeurs dans l’ordre. On peut ainsi préparer un total, rechercher un élément ou afficher une liste de résultats.','const prix = [100, 200, 300];\nlet somme = 0;\nfor (const montant of prix) {\n  somme = somme + montant;\n}\nconsole.log(somme);','600','Combien de valeurs sont parcourues ?',['2','3','4'],1,'Le tableau contient trois valeurs : 100, 200 et 300.']
]),
make('sql','Les données parlent : découvre SQL','BASES DE DONNÉES','tech','Organise des informations et pose tes premières questions à une base de données.','SQL','#dce9f3',[
['Des informations en tableau','Une table organise des données en lignes et en colonnes. Chaque ligne décrit un élément ; chaque colonne décrit une propriété. Une petite bibliothèque peut avoir une table livres avec un titre, un auteur et un identifiant.','id | titre          | stock\n1  | Découvrir Python | 3\n2  | Jardiner         | 5','Deux livres, trois colonnes.','Que représente une ligne dans cet exemple ?',['Un livre','Tous les titres','Une couleur'],0,'Une ligne contient les informations sur un livre.'],
['Choisir des colonnes','SQL est un langage pour interroger une base de données. SELECT précise les colonnes à lire ; FROM indique la table. La requête ne modifie pas les données.','SELECT titre, stock\nFROM livres;','Les titres et les quantités disponibles.','Quel mot indique la table ?',['SELECT','FROM','titre'],1,'FROM indique la table dans laquelle lire les données.'],
['Filtrer avec WHERE','WHERE garde les lignes qui satisfont une condition. Il permet de poser une question précise à un tableau. Par exemple, on peut rechercher seulement les livres dont le stock est supérieur à trois.','SELECT titre\nFROM livres\nWHERE stock > 3;','Jardiner','Quel livre passe le filtre ?',['Découvrir Python, stock 3','Jardiner, stock 5','Les deux'],1,'Seul le stock 5 est strictement supérieur à 3.'],
['Compter et interpréter','COUNT(*) compte des lignes. Un nombre n’est utile que si l’on comprend ce qu’il représente. Compter les titres différents n’est pas la même chose qu’additionner les exemplaires disponibles.','SELECT COUNT(*)\nFROM livres;','2','Le résultat 2 indique…',['Le nombre total d’exemplaires','Le nombre de lignes de livres','Le prix des livres'],1,'COUNT(*) compte les lignes, ici deux titres. Le stock total serait 3 + 5 = 8.']
]),
make('git','Git : garde une trace de tes projets','OUTILS DU DÉVELOPPEUR','tech','Comprends les versions, les commits et le travail à plusieurs.','git','#f3dfd4',[
['Pourquoi conserver des versions ?','Quand un projet évolue, il est utile de retrouver ses anciens états. Git conserve un historique des changements choisis. Il fonctionne localement ; un hébergeur distant est un service complémentaire. Git et GitHub ne sont donc pas la même chose.','Version 1 : un titre\nVersion 2 : un paragraphe\nVersion 3 : une image','Un historique de l’évolution du projet.','À quoi sert principalement Git ?',['Versionner des changements','Dessiner des images','Remplacer Internet'],0,'Git suit l’évolution des fichiers et aide à travailler sur un projet.'],
['Comprendre un commit','Un commit est un état enregistré accompagné d’un message. On prépare les modifications, puis on les enregistre. Un message précis décrit ce qui change, afin de comprendre l’historique plus tard.','git add page.html\ngit commit -m "Ajoute une présentation du projet"','Une étape enregistrée avec un message explicite.','Quel message est le plus utile ?',['truc','Ajoute le bouton de téléchargement','aaaa'],1,'Un message descriptif explique le changement sans devoir ouvrir tous les fichiers.'],
['Explorer une branche','Une branche permet de développer une idée à côté du travail principal. Quand les changements sont prêts, on peut les rapprocher du projet principal. Cela demande parfois de résoudre des modifications qui se contredisent.','main ──●──●────────●\n          ╲        ╱\n           ●──●──●  nouvelle idée','Deux lignes de travail peuvent être réunies.','Une branche permet de…',['Tester une évolution séparément','Supprimer tous les fichiers','Créer une connexion réseau'],0,'Une branche garde une ligne de travail indépendante avant une éventuelle fusion.'],
['Collaborer avec attention','Avant de partager un dépôt, vérifie les fichiers que tu envoies. Ne publie pas de mots de passe, de clés secrètes ni de données personnelles. Relis les changements proposés par les autres et donne un retour précis et respectueux.','Avant de partager :\n✓ Relire les fichiers\n✓ Vérifier les informations privées\n✓ Expliquer les changements','Un projet plus compréhensible et plus sûr.','Que faut-il garder hors d’un dépôt public ?',['Une notice du projet','Une clé secrète','Un exemple sans données privées'],1,'Une clé secrète donne des accès et ne doit pas être publiée.']
]),
make('maths','Les maths qui servent vraiment','MATHÉMATIQUES','maths','Fractions, proportions et probabilités à travers des situations de la vie quotidienne.','½','#e8e0f3',[
['Des parts à comparer','Une fraction décrit un nombre de parts sur un total de parts égales. Le numérateur est en haut, le dénominateur en bas. Deux fractions peuvent représenter la même quantité : partager chaque moitié en deux donne deux quarts pour une moitié.','1/2 = 2/4 = 3/6\nUne moitié reste une moitié.','Des écritures différentes pour une même quantité.','Quelle fraction vaut 1/2 ?',['2/4','1/4','3/4'],0,'Deux parts sur quatre représentent la moitié du total.'],
['Le prix suit la quantité','Deux grandeurs sont proportionnelles quand on passe de l’une à l’autre avec le même coefficient. Si un cahier coûte 250 FCFA, quatre cahiers coûtent quatre fois plus. Vérifie que le prix unitaire reste identique avant d’appliquer cette méthode.','1 cahier → 250 FCFA\n4 cahiers → 4 × 250 = 1 000 FCFA','1 000 FCFA','À prix unitaire constant, 6 cahiers coûtent…',['1 250 FCFA','1 500 FCFA','2 000 FCFA'],1,'6 × 250 = 1 500 FCFA.'],
['Comprendre un pourcentage','Un pourcentage est une proportion sur 100. Pour calculer 10 % d’un montant, on multiplie par 10 puis on divise par 100. Ne confonds pas le montant de la réduction et le prix restant à payer.','Prix : 2 000 FCFA\nRéduction : 10 % = 200 FCFA\nNouveau prix : 1 800 FCFA','Le prix baisse de 200 FCFA.','Que valent 25 % de 100 ?',['4','25','75'],1,'25 % signifie 25 sur 100 : le quart de 100 vaut 25.'],
['Du hasard aux données','Une probabilité décrit une possibilité entre 0 et 1. Avec une pièce équilibrée, les deux faces ont chacune une chance sur deux. Quelques essais ne garantissent pas une répartition exacte ; la variation fait partie du hasard.','Probabilité de pile = 1/2\nProbabilité de face = 1/2\n1/2 + 1/2 = 1','Les probabilités des deux issues totalisent 1.','La probabilité d’un événement impossible est…',['0','1/2','1'],0,'0 représente l’impossibilité ; 1 représente la certitude.']
]),
make('physics','Énergie, mesures & électricité','SCIENCES & TECHNIQUES','sciences','Les premières notions pour comprendre un circuit, une mesure et l’énergie solaire.','⚡','#f3e9bd',[
['Mesurer pour comprendre','Une mesure comporte une valeur et une unité. Le mètre mesure une longueur, la seconde une durée. Convertir les unités permet de comparer correctement les données. Note toujours l’unité avec le résultat.','1 mètre = 100 centimètres\n2 mètres = 200 centimètres','200 cm','Combien valent 3 mètres en centimètres ?',['30 cm','300 cm','3 000 cm'],1,'Chaque mètre vaut 100 cm : 3 × 100 = 300 cm.'],
['Un circuit, une boucle','Un circuit simple relie une source, des conducteurs et un récepteur dans une boucle fermée. Si la boucle est ouverte, le courant ne circule pas dans ce circuit simple. Cette leçon est conceptuelle : ne manipule jamais une prise ou une installation électrique.','Source → conducteur → lampe\n  ↑________________________↓','Une boucle complète permet au courant de circuler.','Dans un circuit simple ouvert, la lampe…',['S’allume toujours','Ne s’allume pas','Crée son énergie'],1,'Le circuit est interrompu ; le courant ne peut pas parcourir la boucle.'],
['Puissance et énergie','La puissance décrit le rythme auquel de l’énergie est transférée. Une puissance en watts multipliée par une durée en heures donne une énergie en wattheures. Un appareil utilisé plus longtemps consomme davantage, à puissance constante.','Lampe : 10 W\nDurée : 3 h\nÉnergie : 10 × 3 = 30 Wh','30 Wh','Une lampe de 5 W utilisée 2 h consomme…',['2,5 Wh','7 Wh','10 Wh'],2,'Énergie = puissance × durée : 5 × 2 = 10 Wh.'],
['Découvrir le solaire','Un panneau photovoltaïque transforme une partie de l’énergie lumineuse en énergie électrique. La production dépend notamment de l’ensoleillement et de l’installation. Une batterie stocke de l’énergie pour un usage ultérieur ; elle n’est pas une source inépuisable.','Lumière → panneau → énergie électrique\nBatterie → stockage','Transformer et stocker sont deux fonctions différentes.','Quel élément sert au stockage ?',['La batterie','La lumière','Une unité de longueur'],0,'La batterie stocke de l’énergie. Son installation relève de professionnels formés.']
]),
make('biology','Comprendre le vivant','BIOLOGIE & SANTÉ','sciences','Cellules, organes et observation : une porte d’entrée vers les sciences et les métiers du soin.','◎','#d9eae5',[
['La cellule, unité du vivant','Les êtres vivants sont constitués de cellules. Certaines formes de vie n’en ont qu’une ; notre organisme en contient de très nombreuses. Une membrane délimite la cellule et contrôle ses échanges. Cette initiation scientifique ne donne pas de conseils de diagnostic ou de traitement.','Cellule → tissu → organe → organisme','Plusieurs niveaux d’organisation du vivant.','Quelle structure délimite une cellule ?',['La membrane','Un dossier informatique','Une règle'],0,'La membrane cellulaire forme une frontière qui participe aux échanges.'],
['Observer sans conclure trop vite','Une observation décrit ce que l’on constate. Une hypothèse propose une explication à vérifier. Une seule observation ne suffit généralement pas pour établir une cause. Dans un travail scientifique, on note les conditions et on compare plusieurs résultats.','Observation : cette plante pousse vers la fenêtre.\nHypothèse : la lumière influence sa croissance.','Une observation n’est pas encore une preuve de cause.','Une hypothèse est…',['Une explication à tester','Toujours une certitude','Une mesure de longueur'],0,'Une hypothèse doit être confrontée à des observations ou à une expérience adaptée.'],
['Des organes qui coopèrent','Un organe regroupe des tissus qui assurent certaines fonctions. Les organes travaillent ensemble dans des systèmes : le cœur contribue à la circulation du sang ; les poumons participent aux échanges gazeux. Les interactions comptent autant que les pièces isolées.','Cellules spécialisées → tissus\nTissus organisés → organes\nOrganes coordonnés → systèmes','Le corps est un ensemble de systèmes liés.','Quel organe contribue à faire circuler le sang ?',['Le cœur','L’écran','La feuille'],0,'Le cœur est une pompe musculaire qui contribue à la circulation sanguine.'],
['Les métiers du soin','Médecins, infirmiers et techniciens de laboratoire ont des missions différentes et complémentaires. Ils suivent des formations reconnues et des règles professionnelles. Les bases de biologie, la communication et la rigueur sont des compétences à explorer dès le lycée.','Observer avec rigueur\nCommuniquer clairement\nRespecter la confidentialité\nPoursuivre une formation reconnue','Une découverte des compétences, pas une qualification.','Ces leçons permettent-elles d’exercer un métier de santé ?',['Oui, immédiatement','Non, une formation reconnue reste nécessaire','Oui, après un quiz'],1,'Une initiation en ligne ne remplace pas les études et autorisations professionnelles requises.']
]),
make('business','D’une idée à un petit projet','COMMERCE & ENTREPRENEURIAT','business','Comprends un besoin, organise un budget et présente une solution utile.','↗','#f4ddcf',[
['Partir d’un besoin','Un projet utile répond à un besoin réel. Avant de fabriquer une solution, écoute les personnes concernées. Pose des questions ouvertes sur leurs difficultés et observe ce qu’elles font déjà. Une idée n’est pas encore une preuve de demande.','Besoin : retrouver ses leçons sans réseau\nPersonnes : élèves avec peu de données\nIdée : des leçons enregistrables','Une solution reliée à un besoin précis.','Quelle question aide à comprendre un besoin ?',['Mon idée est parfaite, non ?','Qu’est-ce qui te bloque aujourd’hui ?','Tu vas acheter tout de suite ?'],1,'Une question ouverte permet à la personne de décrire sa propre expérience.'],
['Distinguer recettes et résultat','Les recettes sont les montants des ventes. Le résultat simplifié correspond aux recettes moins les coûts. Un projet peut vendre beaucoup et conserver peu si ses coûts sont élevés. L’exemple suivant est pédagogique et ne remplace pas une comptabilité complète.','Recettes : 5 000 FCFA\nCoûts : 3 500 FCFA\nRésultat simplifié : 1 500 FCFA','1 500 FCFA','Avec 4 000 de recettes et 3 000 de coûts, il reste…',['1 000 FCFA','3 000 FCFA','7 000 FCFA'],0,'4 000 − 3 000 = 1 000 FCFA.'],
['Tester petit','Un prototype est une version simple qui aide à apprendre. Une maquette papier peut suffire pour tester une idée de service. Regarde ce que la personne arrive à faire sans aide, puis demande ce qui l’a bloquée.','Idée → petit prototype → test\n→ retours → amélioration','Le test sert à apprendre avant de développer davantage.','Pourquoi tester tôt ?',['Pour éviter tous les retours','Pour comprendre ce qui fonctionne','Pour promettre un résultat garanti'],1,'Tester tôt permet d’améliorer une solution à partir d’observations concrètes.'],
['Présenter clairement','Une présentation utile explique à qui s’adresse le projet, quel problème il traite et comment il aide. Donne un exemple concret, puis précise ce qui doit encore être testé. Une promesse claire et modeste est plus crédible qu’un résultat inventé.','Pour [les personnes],\nqui rencontrent [le problème],\nnotre projet permet [l’action utile].','Une phrase pour clarifier ton projet.','Que faut-il préciser dans une présentation ?',['Uniquement le logo','Le public et le besoin','Des chiffres inventés'],1,'Comprendre le public et le besoin aide à évaluer la solution proposée.']
]),
make('agriculture','Agriculture : observer & innover','AGRICULTURE & AGROALIMENTAIRE','agri','Comprends un système de culture et découvre comment les données peuvent aider à l’observer.','❧','#dce8c8',[
['Une culture dans son environnement','Une culture dépend d’un ensemble de facteurs : sol, eau, lumière et pratiques. Les besoins varient selon l’espèce et le contexte local. Avant de proposer une amélioration, observe et note les conditions avec une personne compétente.','Plante + sol + eau + lumière\n+ pratiques + environnement','Un système avec plusieurs facteurs liés.','Avant de changer une pratique, il est utile de…',['Observer le contexte','Copier au hasard','Ignorer le sol'],0,'Observer les conditions locales aide à comprendre ce qui peut expliquer les résultats.'],
['Un carnet d’observation','Un carnet daté permet de suivre les changements. Note la parcelle, la date, l’observation et son unité. Utilise la même méthode pour pouvoir comparer les mesures. Une observation ne permet pas à elle seule d’identifier une maladie ou un traitement.','Date | Parcelle | Hauteur observée\n01/06 | A | 12 cm\n08/06 | A | 16 cm','Une évolution de 4 cm entre deux observations.','Quelle information rend la comparaison plus claire ?',['La date et l’unité','Seulement la couleur du carnet','Un titre sans mesure'],0,'La date situe l’observation et l’unité rend la mesure compréhensible.'],
['Du champ au produit','Une chaîne de valeur comprend plusieurs étapes : production, récolte, transformation éventuelle, transport et vente. Des pertes peuvent apparaître entre les étapes. Les repérer permet de poser de meilleures questions aux professionnels.','Production → récolte → stockage\n→ transformation → transport → vente','Plusieurs métiers participent à un même produit.','Le transport fait-il partie de la chaîne de valeur ?',['Non','Oui','Seulement pour les ordinateurs'],1,'Le transport relie les étapes et les lieux de production, de transformation et de vente.'],
['Un petit tableau utile','Un tableau peut aider à comparer des observations sans outil complexe. Pour deux lots fictifs, calcule une différence ou une moyenne et formule une question. Les conclusions agronomiques nécessitent davantage de données et une expertise adaptée.','Lot A : 20 kg\nLot B : 25 kg\nÉcart : 25 − 20 = 5 kg','Le lot B produit 5 kg de plus dans cet exemple.','Peut-on conclure à la cause avec ces seules données ?',['Oui, certainement','Non, il manque le contexte','Oui, si le tableau est joli'],1,'On connaît l’écart, mais pas les facteurs qui l’expliquent.']
]),
make('logistics','Les coulisses du transport','TRANSPORT & LOGISTIQUE','logistics','Stocks, trajets et organisation : découvre comment un produit arrive à destination.','⇄','#dce6f2',[
['Du départ à l’arrivée','La logistique organise les flux de produits et d’informations. Elle relie notamment l’approvisionnement, le stockage, le transport et la livraison. Un bon suivi permet de savoir où se trouve un produit et quelle étape vient ensuite.','Fournisseur → dépôt → transport\n→ point de livraison → destinataire','Un produit suit plusieurs étapes coordonnées.','La logistique concerne…',['Seulement la conduite','Les flux de produits et d’informations','Uniquement les logos'],1,'Les informations de suivi sont nécessaires pour coordonner les mouvements de produits.'],
['Comprendre un stock','Le stock final est le stock initial augmenté des entrées et diminué des sorties. La même unité doit être utilisée tout au long du calcul. Un comptage réel permet de comparer le registre avec ce qui est présent.','Stock initial : 40 cartons\nEntrées : 15 cartons\nSorties : 12 cartons\nStock final : 43 cartons','40 + 15 − 12 = 43','Avec 10 articles, 4 entrées et 3 sorties, il reste…',['11','17','3'],0,'10 + 4 − 3 = 11 articles.'],
['Planifier un trajet','Une livraison se prépare avec des contraintes : destination, durée, capacité et horaires. Le trajet le plus court n’est pas toujours le plus adapté. La sécurité et les règles de circulation priment sur une simple estimation de vitesse.','Départ : dépôt\nArrivée : destinataire\nÀ vérifier : horaire, capacité, accès','Une planification tient compte de plusieurs contraintes.','Quel facteur compte dans la planification ?',['La capacité du véhicule','La couleur de la facture uniquement','Un temps inventé'],0,'La capacité limite la quantité qui peut être transportée.'],
['Tracer une livraison','La traçabilité conserve les informations utiles sur une étape : référence, date, quantité et statut. Évite d’enregistrer ou de diffuser des données personnelles qui ne sont pas nécessaires. Les noms et adresses de clients doivent être protégés.','Référence : COL-014\nQuantité : 3 cartons\nStatut : livré\nDate : 12/06','Une trace claire sans détails privés inutiles.','Quelle information permet d’identifier un colis sans nom de client ?',['Une référence de colis','Un mot de passe','Une photo privée'],0,'Une référence suit le colis sans révéler inutilement l’identité du destinataire.']
]),
make('design','Créer une expérience qui aide','DESIGN & COMMUNICATION','creative','Imagine une interface lisible, dessine une maquette et teste-la avec quelqu’un.','✺','#e9dded',[
['Concevoir pour quelqu’un','Le design commence par une tâche et les personnes qui doivent la réaliser. Un écran utile aide à comprendre quoi faire. Avant de choisir les couleurs, écris l’action principale et les obstacles que l’interface doit réduire.','Personne : une lycéenne\nObjectif : retrouver un cours\nAction principale : continuer la leçon','Le design sert une tâche concrète.','Par quoi commencer ?',['Les besoins des utilisateurs','Une animation au hasard','Un écran plein de boutons'],0,'Les besoins aident à choisir les éléments réellement utiles.'],
['Rendre le texte lisible','Une hiérarchie claire aide à parcourir une page : un titre principal, des sous-titres et des paragraphes courts. Utilise un contraste suffisant et ne fais pas dépendre une information de la couleur seule.','Titre → idée principale\nSous-titre → partie\nTexte → explication\nBouton → action précise','Chaque élément joue un rôle.','Un bouton clair peut s’appeler…',['Clique ici ici','Télécharger la leçon','???'],1,'Un verbe et un objet expliquent ce qui va se passer.'],
['Dessiner une maquette','Une maquette représente l’organisation d’un écran. Papier et crayon suffisent. Dessine les zones importantes, puis demande à une personne de montrer où elle cliquerait pour réaliser une tâche. Observe avant d’expliquer.','[Titre du cours]\n[Progression]\n[Continuer]\n[Liste des leçons]','Une structure simple à tester.','Quel outil suffit pour une première maquette ?',['Du papier et un crayon','Un serveur coûteux','Un téléphone neuf'],0,'Une maquette papier permet déjà de vérifier l’organisation et les libellés.'],
['Améliorer grâce aux retours','Un test observe une tâche, pas la valeur de la personne. Demande par exemple : « Comment enregistrerais-tu cette leçon ? » Si la personne hésite, l’interface peut être améliorée. Change un élément, puis teste à nouveau.','Observer → écouter → modifier\n→ tester une nouvelle fois','Le produit progresse avec les retours.','Que faire si un bouton est difficile à trouver ?',['Blâmer la personne','Revoir son emplacement ou son libellé','Ajouter dix boutons'],1,'L’hésitation révèle une occasion d’améliorer l’interface.']
]),
make('security','Les réflexes de sécurité numérique','CYBERSÉCURITÉ','tech','Apprends à repérer les messages suspects et à protéger ton identité en ligne.','⌁','#d8e9e4',[
['Repérer une demande suspecte','Un message peut imiter une organisation connue pour obtenir une information privée. L’urgence, la menace et une demande de code sont des signaux d’alerte. Vérifie la demande par un canal officiel que tu connais déjà.','Message : « Donne ton code tout de suite ! »\nRéflexe : ne pas transmettre le code.','Prendre le temps de vérifier.','Quelle demande est un signal d’alerte ?',['Une demande de code de connexion','Une explication de cours','Une date publique'],0,'Un code de connexion est privé et peut donner accès à un compte.'],
['Une sauvegarde, une deuxième chance','Une sauvegarde est une copie que tu peux restaurer si l’original est perdu. Une copie sur le même appareil ne suffit pas si cet appareil disparaît. Vérifie régulièrement que la sauvegarde peut être ouverte.','Original sur le téléphone\n+ copie sur un autre support\n+ vérification de la restauration','Une copie utile doit être récupérable.','Si toutes les copies restent sur le même téléphone…',['La perte du téléphone peut tout supprimer','Il n’y a plus aucun risque','Internet les protège forcément'],0,'Un autre support réduit le risque de tout perdre avec l’appareil.'],
['Gérer les autorisations','Une application peut demander l’accès à la caméra, aux contacts ou à la position. Demande-toi si cet accès sert la fonction utilisée. Refuser une autorisation inutile limite les informations partagées.','Fonction : lire un cours\nQuestion : les contacts sont-ils nécessaires ?','Donner seulement les accès utiles.','Une appli de lecture a-t-elle toujours besoin de tes contacts ?',['Oui','Non','Seulement le dimanche'],1,'Une lecture de leçon ne nécessite généralement pas l’accès aux contacts.'],
['Partager avec discernement','Avant de publier, vérifie si le contenu expose quelqu’un : adresse, document privé, visage ou emploi du temps. Une publication peut circuler au-delà du public prévu. Demande l’accord des personnes concernées.','Avant de publier :\nQui est visible ?\nQuelles données apparaissent ?\nAi-je l’accord nécessaire ?','Un moment de vérification évite une exposition inutile.','Avant de publier une photo d’un camarade…',['Demande son accord','Cache seulement ton nom','Publie sans réfléchir'],0,'L’accord et la protection des données personnelles comptent.']
]),
make('data','Lire, comprendre & raconter les données','DONNÉES & STATISTIQUES','maths','Passe d’un tableau à une conclusion prudente, avec des exemples concrets.','▥','#e1e5f4',[
['Une donnée a un contexte','Une donnée est une information recueillie. Sans unité, date ou méthode, elle peut être difficile à interpréter. « 20 » ne dit pas s’il s’agit de personnes, de kilogrammes ou de minutes.','Valeur : 20\nUnité : élèves\nContexte : présents ce matin','Le contexte donne un sens au nombre.','Quelle donnée est la plus interprétable ?',['20','20 élèves présents le 12 juin','Beaucoup'],1,'La valeur, l’unité et la date rendent l’information plus claire.'],
['Calculer une moyenne','La moyenne additionne les valeurs puis divise le total par leur nombre. Elle résume une série, mais peut masquer des écarts. Pour comprendre un groupe, regarde aussi les valeurs individuelles.','Valeurs : 4, 6, 8\nSomme : 18\nMoyenne : 18 / 3 = 6','6','Quelle est la moyenne de 2, 4 et 6 ?',['3','4','6'],1,'(2 + 4 + 6) / 3 = 12 / 3 = 4.'],
['Choisir un graphique','Des barres comparent des catégories. Une courbe peut montrer une évolution dans le temps. N’oublie pas les titres, les unités et une échelle compréhensible. Un graphique très décoré n’est pas forcément plus informatif.','Barres → comparer des catégories\nCourbe → suivre une évolution','Le graphique dépend de la question.','Pour suivre une quantité chaque semaine, on peut utiliser…',['Une courbe chronologique','Un titre sans données','Un mot de passe'],0,'Une courbe sur un axe temporel aide à suivre l’évolution.'],
['Interpréter avec prudence','Deux grandeurs peuvent évoluer ensemble sans que l’une cause l’autre. Une enquête sur quelques personnes ne décrit pas forcément toute une population. Présente la méthode, les limites et les questions encore ouvertes.','Résultat observé ≠ cause prouvée\nPetit échantillon ≠ population entière','Une conclusion précise respecte les limites des données.','Une association prouve-t-elle une cause ?',['Toujours','Non, pas à elle seule','Oui, si le graphique est beau'],1,'D’autres facteurs peuvent expliquer l’association observée.']
]),
make('hospitality','Accueillir, communiquer & organiser','TOURISME & SERVICES','services','Découvre les compétences de l’accueil à travers des situations simples.','☷','#f2e3cc',[
['Comprendre une demande','Un accueil utile commence par écouter. Reformule la demande pour vérifier ta compréhension. Ne promets pas un service dont tu ne connais pas la disponibilité. Une réponse claire et respectueuse est plus utile qu’une réponse rapide et incertaine.','« Si je comprends bien, vous cherchez\nun lieu pour un groupe de six personnes ? »','Reformuler permet de vérifier le besoin.','Pourquoi reformuler ?',['Pour vérifier qu’on a compris','Pour interrompre la personne','Pour promettre sans vérifier'],0,'Reformuler confirme les informations avant de proposer une solution.'],
['Organiser une réservation','Un tableau simple peut suivre une date, une référence, une capacité et un statut. Ne collecte que les informations nécessaires. Vérifie les disponibilités avant de confirmer une réservation.','Référence : RES-021\nDate : 15/07\nGroupe : 6 personnes\nStatut : à confirmer','Un suivi distingue demande et confirmation.','Avant de confirmer, que faut-il vérifier ?',['La disponibilité','Le nombre de couleurs du tableau','La météo de l’année passée'],0,'Une confirmation dépend d’une disponibilité réelle.'],
['Calculer une prestation','Le prix total d’une prestation simple se calcule avec le prix unitaire et la quantité. Indique clairement ce qui est compris. Les montants de cet exercice sont fictifs et ne représentent aucun tarif réel au Togo.','Exemple fictif : 2 000 FCFA par personne\nGroupe : 4 personnes\nTotal : 8 000 FCFA','4 × 2 000 = 8 000','Pour 3 personnes au même prix, le total est…',['5 000 FCFA','6 000 FCFA','9 000 FCFA'],1,'3 × 2 000 = 6 000 FCFA.'],
['Présenter un lieu avec respect','Une présentation de lieu distingue les faits vérifiés, les conseils et les goûts personnels. Demande l’accord avant de photographier des personnes et respecte les règles locales. Une information incertaine doit être vérifiée plutôt qu’inventée.','Description factuelle\nAccès à vérifier\nRègles du lieu\nRespect des personnes','Informer clairement, sans inventer.','Si tu ne connais pas une information…',['Invente une réponse','Dis-le et cherche à vérifier','Change discrètement le prix'],1,'Reconnaître l’incertitude aide à fournir une information fiable.']
])];}
